changeSet.sql:
CREATE FUNCTION catalog_classification_level_rank(level_code varchar) RETURNS integer LANGUAGE sql IMMUTABLE AS $$ SELECT CASE level_code WHEN 'PUBLIC' THEN 0 WHEN 'INTERNAL' THEN 1 WHEN 'SECRET' THEN 2 WHEN 'CONFIDENTIAL' THEN 3 ELSE NULL END $$;
CREATE FUNCTION guard_catalog_classification_snapshot() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.subject_type IS DISTINCT FROM OLD.subject_type OR NEW.subject_key IS DISTINCT FROM OLD.subject_key OR NEW.asset_type IS DISTINCT FROM OLD.asset_type OR NEW.declared_level IS DISTINCT FROM OLD.declared_level OR NEW.origin_type IS DISTINCT FROM OLD.origin_type OR NEW.origin_ref IS DISTINCT FROM OLD.origin_ref OR NEW.sealed_at IS DISTINCT FROM OLD.sealed_at OR NEW.evidence_checksum IS DISTINCT FROM OLD.evidence_checksum THEN RAISE EXCEPTION 'classification source evidence is immutable'; END IF;
IF catalog_classification_level_rank(NEW.effective_level) < catalog_classification_level_rank(OLD.effective_level) THEN RAISE EXCEPTION 'effective classification cannot be lowered'; END IF; IF OLD.detected_level IS NOT NULL AND ( NEW.detected_level IS NULL OR catalog_classification_level_rank(NEW.detected_level) < catalog_classification_level_rank(OLD.detected_level) ) THEN RAISE EXCEPTION 'detected classification cannot be lowered'; END IF; IF OLD.manual_floor IS NOT NULL AND ( NEW.manual_floor IS NULL OR catalog_classification_level_rank(NEW.manual_floor) < catalog_classification_level_rank(OLD.manual_floor) ) THEN RAISE EXCEPTION 'manual classification floor cannot be lowered'; END IF; RETURN NEW; END; $$;
CREATE TRIGGER trg_catalog_classification_snapshot_guard BEFORE UPDATE ON catalog_classification_snapshot FOR EACH ROW EXECUTE FUNCTION guard_catalog_classification_snapshot();
CREATE FUNCTION reject_catalog_classification_event_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'classification events are append-only'; END; $$;
CREATE TRIGGER trg_catalog_classification_event_immutable BEFORE UPDATE OR DELETE ON catalog_classification_event FOR EACH ROW EXECUTE FUNCTION reject_catalog_classification_event_mutation();

rollback.sql:
DROP TRIGGER IF EXISTS trg_catalog_classification_event_immutable ON catalog_classification_event;
DROP FUNCTION IF EXISTS reject_catalog_classification_event_mutation();
DROP TRIGGER IF EXISTS trg_catalog_classification_snapshot_guard ON catalog_classification_snapshot;
DROP FUNCTION IF EXISTS guard_catalog_classification_snapshot();
DROP FUNCTION IF EXISTS catalog_classification_level_rank(varchar);
